previewCss:
.darma-loader-darma-b14-tape-dispenser { --accent: var(--loader-color, #facc15); --accent-2: var(--loader-secondary-color, #475569); width: var(--loader-size, 120px); height: calc(var(--loader-size, 120px) * .7); position: relative; }
.darma-loader-darma-b14-tape-dispenser::after { content: ''; position: absolute; bottom: 0; left: 0; width: 100%; height: 22%; border-radius: 4px 22% 4px 4px; background: linear-gradient(var(--accent-2), color-mix(in srgb, #000 32%, var(--accent-2))); }
.darma-loader-darma-b14-tape-dispenser::before { content: ''; position: absolute; z-index: 2; bottom: 20%; right: 3%; width: 22%; height: 9%; background: color-mix(in srgb, #000 40%, var(--accent-2)); clip-path: polygon(0 0, 100% 0, 100% 100%, 90% 36%, 80% 100%, 70% 36%, 60% 100%, 50% 36%, 40% 100%, 30% 36%, 20% 100%, 10% 36%, 0 100%); }
.darma-loader-darma-b14-tape-dispenser .darma-loader-darma-b14-tape-dispenser__roll { position: absolute; bottom: 20%; left: 7%; width: 44%; height: 62%; border-radius: 50%; background: conic-gradient(from 0deg, var(--accent) 0 47%, color-mix(in srgb, #000 26%, var(--accent)) 47% 50%, var(--accent) 50% 97%, color-mix(in srgb, #000 26%, var(--accent)) 97% 100%); box-shadow: inset 0 0 0 calc(var(--loader-size, 120px) * .075) color-mix(in srgb, #fff 66%, var(--accent-2)); animation: darma-loader-darma-b14-tape-dispenser-roll-spin calc(var(--loader-speed, 1s) * 2.4) linear infinite; }
.darma-loader-darma-b14-tape-dispenser .darma-loader-darma-b14-tape-dispenser__roll::after { content: ''; position: absolute; inset: 34%; border-radius: 50%; background: color-mix(in srgb, #000 22%, var(--accent-2)); }
.darma-loader-darma-b14-tape-dispenser span { position: absolute; bottom: 27%; left: 47%; height: 5%; border-radius: 1px; background: color-mix(in srgb, #fff 58%, var(--accent)); animation: darma-loader-darma-b14-tape-dispenser-pull-tape calc(var(--loader-speed, 1s) * 2.4) ease-in-out infinite; }
@keyframes darma-loader-darma-b14-tape-dispenser-roll-spin { to { transform: rotate(-360deg); } }
@keyframes darma-loader-darma-b14-tape-dispenser-pull-tape { 0% { width: 4%; } 66% { width: 44%; } 100% { width: 4%; } }

